private fun AncNavHost() {
  val navController = rememberNavController()
  NavHost(navController = navController, startDestination = "patients") {
    composable("patients") {
      PatientListScreen(onPatientClick = { id -> navController.navigate("patients/$id") })
    }
    composable(
      "patients/{patientId}",
      arguments = listOf(navArgument("patientId") { type = NavType.LongType }),
    ) { entry ->
      val patientId = entry.arguments!!.getLong("patientId")
      PatientDetailScreen(
        patientId = patientId,
        onBack = { navController.popBackStack() },
        onRecordVisit = { navController.navigate("patients/$patientId/new-visit") },
      )
    }
    composable(
      "patients/{patientId}/new-visit",
      arguments = listOf(navArgument("patientId") { type = NavType.LongType }),
    ) { entry ->
      val patientId = entry.arguments!!.getLong("patientId")
      VisitFormScreen(patientId = patientId, onDone = { navController.popBackStack() })
    }
  }
}

